export type VerifyPayment = ({
    mode,
    Payment,
    Token,
    ApprovalURL,
    ReturnHost,
}: {
    mode?: 'add-card';
    Payment?: CardPayment;
    Token: string;
    ApprovalURL?: string;
    ReturnHost?: string;
}) => Promise<TokenPaymentMethod>;

export const assertChargeablePaymentToken = async (api: Api, Token: string, signal?: AbortSignal): Promise<void> => {
    if (signal?.aborted) {
        throw new Error(c('Error').t`Process aborted`);
    }
    const { Status } = await api({ ...getTokenStatus(Token), signal });
    if (Status !== STATUS_CHARGEABLE) {
        throw new Error(c('Error').t`Payment process canceled`);
    }
};

export const getDefaultVerifyPayment = (createModal: (modal: JSX.Element) => void, api: Api): VerifyPayment => {
    const verify: VerifyPayment = async ({ mode, Payment, Token, ApprovalURL, ReturnHost }) =>
        new Promise<TokenPaymentMethod>((resolve, reject) => {
            createModal(
                <PaymentVerificationModal
                    mode={mode}
                    payment={Payment}
                    token={Token}
                    onSubmit={resolve}
                    onClose={reject}
                    onProcess={() => {
                        const abort = new AbortController();
                        return {
                            promise: process({ Token, api, ReturnHost, ApprovalURL, signal: abort.signal }).then(() =>
                                assertChargeablePaymentToken(api, Token, abort.signal)
                            ),
                            abort,
                        };
                    }}
                />
            );
        });
    return verify;
};

/** Create a token and delegate pending verification to the supplied strategy. */
export const createPaymentToken = async (
    {
        params,
        api,
        verify,
        mode,
    }: {
        verify: VerifyPayment;
        mode?: 'add-card';
        api: Api;
        params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment;
    },
    amountAndCurrency?: AmountAndCurrency
): Promise<TokenPaymentMethod> => {
    if (isTokenPaymentMethod(params)) {
        return params;
    }

    const { Token, Status, ApprovalURL, ReturnHost } = await fetchPaymentToken({ params, api }, amountAndCurrency);
    if (Status === STATUS_CHARGEABLE) {
        return toTokenPaymentMethod(Token);
    }
    if (Status !== STATUS_PENDING) {
        const message =
            Status === STATUS_FAILED
                ? c('Error').t`Payment process failed`
                : Status === STATUS_CONSUMED
                ? c('Error').t`Payment process consumed`
                : Status === STATUS_NOT_SUPPORTED
                ? c('Error').t`Payment process not supported`
                : c('Error').t`Unknown payment token status`;
        throw new Error(message);
    }

    let Payment: CardPayment | undefined;
    if (!isExistingPayment(params)) {
        Payment = params.Payment;
    }
    return verify({ mode, Payment, Token, ApprovalURL, ReturnHost });
};

